{"command": "cd ~/repo-a && cat > package.json <<'EOF'
{
  "name": "shopping-api",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "main": "server.js",
  "scripts": { "start": "node server.js", "test": "node test.js" }
}
EOF
cat > server.js <<'EOF'
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';

const PORT = Number(process.env.PORT || 8080);
const DB_PATH = process.env.DB_PATH || '/data/shopping.db';
fs.mkdirSync(path.dirname(DB_PATH), { recursive: true });

const db = new DatabaseSync(DB_PATH);
db.exec('PRAGMA journal_mode = WAL;');
db.exec(`CREATE TABLE IF NOT EXISTS items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  text TEXT NOT NULL,
  bought INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);`);
db.exec('CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL);');
db.prepare("INSERT INTO meta(k,v) VALUES('version','0') ON CONFLICT(k) DO NOTHING").run();

const bumpVersion = () => {
  db.prepare("UPDATE meta SET v = CAST(CAST(v AS INTEGER)+1 AS TEXT) WHERE k='version'").run();
  return version();
};
const version = () => Number(db.prepare("SELECT v FROM meta WHERE k='version'").get().v);
const now = () => new Date().toISOString();
const row = (r) => r && ({ id: r.id, text: r.text, bought: !!r.bought, updated_at: r.updated_at });

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET,POST,PUT,DELETE,OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type',
  'Access-Control-Max-Age': '86400',
};

function send(res, code, body, extra = {}) {
  const headers = { ...CORS, ...extra };
  if (body === undefined || code === 204) { res.writeHead(code, headers); return res.end(); }
  const data = JSON.stringify(body);
  headers['Content-Type'] = 'application/json; charset=utf-8';
  headers['Content-Length'] = Buffer.byteLength(data);
  res.writeHead(code, headers);
  res.end(data);
}
const err = (res, code, message) => send(res, code, { error: message });

function readBody(req, limit = 1024 * 1024) {
  return new Promise((resolve, reject) => {
    let size = 0; const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > limit) { reject(Object.assign(new Error('body too large'), { code: 413 })); req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8').trim();
      if (!raw) return resolve({});
      try { const v = JSON.parse(raw); resolve(v && typeof v === 'object' ? v : {}); }
      catch { reject(Object.assign(new Error('invalid JSON'), { code: 400 })); }
    });
    req.on('error', reject);
  });
}

const allItems = () => db.prepare('SELECT * FROM items ORDER BY id ASC').all().map(row);
const getItem = (id) => row(db.prepare('SELECT * FROM items WHERE id = ?').get(id));

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const parts = url.pathname.split('/').filter(Boolean);
  const method = req.method;

  if (method === 'OPTIONS') return send(res, 204);
  try {
    if (parts.length === 0 && method === 'GET') {
      return send(res, 200, { service: 'shopping-api', ok: true, endpoints: ['GET /items', 'POST /items', 'PUT /items/:id', 'DELETE /items/:id', 'GET /health'] });
    }
    if (parts[0] === 'health' && method === 'GET') {
      db.prepare('SELECT 1').get();
      return send(res, 200, { ok: true, version: version() });
    }
    if (parts[0] === 'version' && method === 'GET') return send(res, 200, { version: version() });

    if (parts[0] === 'items' && parts.length === 1) {
      if (method === 'GET') return send(res, 200, { version: version(), items: allItems() });
      if (method === 'POST') {
        const body = await readBody(req);
        if (body.bought !== undefined && typeof body.bought !== 'boolean') return err(res, 400, 'bought must be boolean');
        if ('id' in body && body.id !== null) return err(res, 400, 'id is assigned by the server');
        const text = typeof body.text === 'string' ? body.text.trim() : '';
        if (!text) return err(res, 400, 'text required');
        const info = db.prepare('INSERT INTO items(text,bought,updated_at) VALUES(?,?,?)').run(text, body.bought ? 1 : 0, now());
        bumpVersion();
        return send(res, 201, getItem(Number(info.lastInsertRowid)));
      }
      // PUT /items  -> atomic full replace (optional convenience)
      if (method === 'PUT') {
        const body = await readBody(req);
        if (!Array.isArray(body.items)) return err(res, 400, 'items array required');
        const clean = [];
        for (const it of body.items) {
          if (!it || typeof it.text !== 'string' || !it.text.trim()) return err(res, 400, 'each item needs text');
          clean.push({ text: it.text.trim(), bought: it.bought === true, id: Number.isInteger(it.id) ? it.id : null });
        }
        db.exec('BEGIN');
        try {
          db.exec('DELETE FROM items');
          const ins = db.prepare('INSERT INTO items(id,text,bought,updated_at) VALUES(?,?,?,?)');
          for (const it of clean) ins.run(it.id, it.text, it.bought ? 1 : 0, now());
          db.exec('COMMIT');
        } catch (e) { db.exec('ROLLBACK'); throw e; }
        bumpVersion();
        return send(res, 200, { version: version(), items: allItems() });
      }
      return err(res, 405, 'method not allowed');
    }

    if (parts[0] === 'items' && parts.length === 2) {
      const id = Number(parts[1]);
      if (!Number.isInteger(id) || id <= 0) return err(res, 400, 'bad id');
      const existing = getItem(id);
      if (method === 'GET') return existing ? send(res, 200, existing) : err(res, 404, 'not found');
      if (method === 'PUT') {
        if (!existing) return err(res, 404, 'not found');
        const body = await readBody(req);
        let text = existing.text, bought = existing.bought ? 1 : 0;
        if (body.text !== undefined) {
          if (typeof body.text !== 'string' || !body.text.trim()) return err(res, 400, 'text required');
          text = body.text.trim();
        }
        if (body.bought !== undefined) {
          if (typeof body.bought !== 'boolean') return err(res, 400, 'bought must be boolean');
          bought = body.bought ? 1 : 0;
        }
        db.prepare('UPDATE items SET text=?, bought=?, updated_at=? WHERE id=?').run(text, bought, now(), id);
        bumpVersion();
        return send(res, 200, getItem(id));
      }
      if (method === 'DELETE') {
        if (!existing) return err(res, 404, 'not found');
        db.prepare('DELETE FROM items WHERE id=?').run(id);
        bumpVersion();
        return send(res, 204);
      }
      return err(res, 405, 'method not allowed');
    }

    return err(res, 404, 'no such endpoint');
  } catch (e) {
    if (e && e.code === 400) return err(res, 400, e.message);
    if (e && e.code === 413) return err(res, 413, e.message);
    console.error('error handling', method, url.pathname, e);
    if (!res.headersSent) return err(res, 500, 'internal error');
  }
});

server.listen(PORT, '0.0.0.0', () => console.log(`shopping-api listening on :${PORT}, db ${DB_PATH}`));
for (const sig of ['SIGTERM', 'SIGINT']) process.on(sig, () => { server.close(() => { try { db.close(); } catch {} process.exit(0); }); setTimeout(() => process.exit(0), 2000).unref(); });
EOF
node --check server.js && echo SYNTAX_OK"}

