cat > test.js <<'EOF'
// End-to-end check against a running api. Usage: BASE=http://127.0.0.1:8080 node test.js
const BASE = process.env.BASE || 'http://127.0.0.1:8080';
let fails = 0;
const ok = (cond, msg) => { if (cond) console.log('ok   ' + msg); else { fails++; console.log('FAIL ' + msg); } };
const j = async (method, p, body) => {
  const r = await fetch(BASE + p, { method, headers: body ? { 'content-type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined });
  const t = await r.text();
  return { status: r.status, body: t ? JSON.parse(t) : null };
};
(async () => {
  ok((await j('GET', '/health')).status === 200, 'health');
  const a = await j('POST', '/items', { text: 'test-milk' });
  ok(a.status === 201 && a.body.id > 0 && a.body.bought === false, 'create item');
  const b = await j('POST', '/items', { text: ' ' });
  ok(b.status === 400, 'reject empty text');
  const list = await j('GET', '/items');
  ok(list.status === 200 && list.body.items.some((i) => i.id === a.body.id), 'list contains item');
  const u = await j('PUT', '/items/' + a.body.id, { bought: true });
  ok(u.status === 200 && u.body.bought === true, 'mark bought');
  ok((await j('PUT', '/items/999999', { bought: true })).status === 404, '404 on missing');
  ok((await j('PUT', '/items/' + a.body.id, { text: 'test-milk2' })).body.text === 'test-milk2', 'rename');
  const after = await j('GET', '/items');
  ok(after.body.items.find((i) => i.id === a.body.id).bought === true, 'bought persists');
  ok((await j('DELETE', '/items/' + a.body.id)).status === 204, 'delete');
  ok(!(await j('GET', '/items')).body.items.some((i) => i.id === a.body.id), 'deleted gone');
  console.log(fails ? `\n${fails} FAILED` : '\nALL PASSED');
  process.exit(fails ? 1 : 0);
})();
EOF
